import{_ as e,o as t,c as i,a6 as a}from"./chunks/framework.BBIckNDn.js";const p=JSON.parse('{"title":"第16章 Unityの内部 ── 「内部実装を想像できる」ようになる","description":"","frontmatter":{"title":"第16章 Unityの内部 ── 「内部実装を想像できる」ようになる","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"Unityはソース非公開(参照用C#部分を除く)だが、ここまでの知識があれば 内部を高精度で推測できる。「GetComponentはなぜ遅い」「GC Allocを なぜ避ける」「IL2CPPとは何か」「DOTSはなぜ速い」── これらを"}},"headers":[],"relativePath":"guide/low-level/unity-internals.md","filePath":"guide/low-level/unity-internals.md"}'),n={name:"guide/low-level/unity-internals.md"};function o(s,l,r,d,c,u){return t(),i("div",null,[...l[0]||(l[0]=[a(`<h1 id="第16章-unityの内部-──-「内部実装を想像できる」ようになる" tabindex="-1">第16章 Unityの内部 ── 「内部実装を想像できる」ようになる <a class="header-anchor" href="#第16章-unityの内部-──-「内部実装を想像できる」ようになる" aria-label="Permalink to &quot;第16章 Unityの内部 ── 「内部実装を想像できる」ようになる&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>Unityはソース非公開(参照用C#部分を除く)だが、ここまでの知識があれば <strong>内部を高精度で推測できる</strong>。「GetComponentはなぜ遅い」「GC Allocを なぜ避ける」「IL2CPPとは何か」「DOTSはなぜ速い」── これらを 仕組みから説明できることが、Unityでの設計力・最適化力に直結する。 また「マネージド言語がネイティブとどう共存するか」という主題は スクリプト搭載エンジン全般(Lua, GDScript等)に通じる一般教養である。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>Unityの2世界構造(C++エンジンコア+C#ユーザーコード)を説明できる</li><li>C#のコンパイルと実行(IL→Mono JIT / IL2CPP AOT)を説明できる</li><li>GCの仕組み(世代別/インクリメンタル)とGC Alloc回避術を原理から説明できる</li><li>GameObject/Componentの内部表現とGetComponent等のコストを推測できる</li><li>DOTS(ECS/Jobs/Burst)がこれまでの章のどの原理の応用かを説明できる</li><li>Unityプロファイラ/Frame Debuggerで問題を切り分けられる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第7章(コンパイラ・JIT/AOTの語彙)、第8章(スレッド)、第9章(C++)、 第15章(エンジン一般論)。C#の基本文法(適宜補う)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>Unityの全体構造</strong><ul><li>ネイティブC++コア(レンダラ・物理PhysX・アセット・シーン管理) <ul><li>マネージドC#層(ユーザースクリプト+参照実装UnityCsReference)</li></ul></li><li>C#⇔C++の境界(internal call / P-Invoke的ブリッジ)── 「Transform.positionのgetが関数呼び出しでネイティブへ渡る」コスト</li><li>PlayerLoop: ネイティブ側のゲームループが各C# Update群を呼ぶ (第14章の図と対応させる)</li></ul></li><li><strong>C#の実行モデル</strong><ul><li>C# → IL(中間言語)→ (a) Mono: <strong>JIT</strong>コンパイル (b) <strong>IL2CPP</strong>: ILをC++に変換→各プラットフォームのC++コンパイラで AOTコンパイル(第7章の全知識で読める)</li><li>IL2CPPの生成コードを実際に読む(ジェネリック展開・メソッド表)</li><li>AOTの制約(実行時コード生成不可)とジェネリクスの落とし穴</li></ul></li><li><strong>メモリとGC</strong><ul><li>マネージドヒープ / ネイティブヒープの2重構造 (プロファイラの「GC Alloc」と「Native Memory」の区別)</li><li>Boehm GC(保守的・非移動)→ インクリメンタルGCの現状</li><li><strong>GCスパイクの正体</strong>(マーク&amp;スイープの停止時間)</li><li>GC Alloc回避のイディオムがなぜ効くかを原理から: 文字列結合・ボクシング・クロージャ・LINQ・yield が確保する理由</li><li>struct(値型)とclass(参照型)のメモリレイアウト ── 第3,6章の直結</li></ul></li><li><strong>GameObject/Componentの内部像</strong><ul><li>GameObjectは「Componentポインタのリストを持つネイティブオブジェクト」</li><li>C#側オブジェクトはネイティブへの<strong>ハンドル/ラッパ</strong>として理解する。 通常の <code>Destroy(obj)</code> は破棄を予約し、実際の破棄は現在のUpdateループ後・描画前に行われる。 呼出し直後に必ず <code>obj == null</code> がtrueになるという意味ではない。実体の破棄後も C#参照は残り得るが、UnityEngine.Objectの <code>== null</code> はnative側の存在も判定するため、 <code>ReferenceEquals(obj, null)</code> と結果が異なる場合がある(Unity 6.0の仕様)</li><li>GetComponent(型検索)・Find系(名前検索)のコストを内部像から推測</li><li>Transform階層の更新(dirty伝播)、SetActiveのコスト</li></ul></li><li><strong>アセットとシリアライズ</strong><ul><li>メタファイル・GUID、AssetBundle/Addressables(第15章クックの実物)</li><li>シリアライズの規則(なぜpublicフィールドか、SerializeField)</li></ul></li><li><strong>レンダリングパス</strong><ul><li>Built-in / URP / HDRP(SRP: C#で描画パイプラインを記述する設計)</li><li>バッチング(static/dynamic/SRP Batcher/GPU instancing)の中身 ── 第13章ドローコール知識の応用</li><li>Frame Debuggerでドローコール列を読む(RenderDoc併用)</li></ul></li><li><strong>DOTS ── これまでの全章の答え合わせ</strong><ul><li>ECS(アーキタイプ型: 第15章)、C# Job System(第8章ジョブ+ 安全性チェック)、<strong>Burst</strong>(LLVMベースのSIMD最適化コンパイラ: 第4章の目で出力アセンブリを読む)</li><li>NativeArray/Allocator(第6章アロケータの実物)</li><li>「DOTSはなぜ速いか」を3つの章(3,8,4)で説明できるようにする</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>2世界構造とブリッジコスト</strong> ── Unity最適化の第一原理</li><li><strong>JIT vs AOT(IL2CPP)</strong> ── プラットフォーム対応とビルドの理解</li><li><strong>GC Allocは「原理的に」追跡できる</strong> ── 迷信でなく仕組みで回避</li><li><strong>C#オブジェクト=ネイティブへのハンドル</strong> ── null挙動・寿命の謎の解</li><li><strong>DOTS=データ指向の産業実装</strong></li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>GCスパイクでカクつく</td><td>GCの停止・Alloc追跡</td></tr><tr><td>Update内のGetComponent禁止規約</td><td>ブリッジ+型検索コスト</td></tr><tr><td>Destroyしたのに== nullにならない系の混乱</td><td>ハンドル構造・演算子オーバーロード</td></tr><tr><td>iOSビルドはIL2CPP必須</td><td>AOT制約</td></tr><tr><td>SetPass Calls/Batchesの削減</td><td>バッチング内部</td></tr><tr><td>大量ユニットはDOTSで</td><td>ECS/Jobs/Burst</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>UnityCsReference(GitHub)で <code>MonoBehaviour</code> や <code>GameObject</code> の C#側実装を読み、ネイティブ呼び出し(extern)との境界を確認せよ。</li><li>IL2CPPビルドの生成C++(<code>Il2CppOutputProject</code>)から自分のスクリプトの 変換結果を探して読め。ILSpyでILも見よ(C#→IL→C++の3層対照)。</li><li>Profilerで「GC Allocが出る書き方」10種(文字列結合、LINQ、 ボクシング、クロージャ等)を意図的に書き、ゼロにする書き換えをせよ。</li><li><code>struct</code> 100万要素の配列と <code>class</code> 100万インスタンスの走査速度を 比較し、第3章の言葉で説明せよ。</li><li>Frame Debugger+RenderDocで自作シーンのドローコール列を読み、 SRP Batcherの効果を確認せよ。</li><li>同じ「1万体の移動」をMonoBehaviour版とDOTS(ECS+Jobs+Burst)版で 実装し、プロファイラで比較。Burst Inspectorで出力アセンブリを読め (第4章の実戦投入)。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『Unityパフォーマンスチューニングバイブル』(CyberAgent、無料公開)── 和書系で最実務的。内部の裏取りに最適</li><li>Unity公式マニュアル「メモリ」「IL2CPP」「SRP」章(一次情報)</li><li>『CLR via C#』── .NETランタイムの深掘り(発展)</li><li>Catlike Coding(Web)── URP/シェーダ/DOTSの良質チュートリアル</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>UnityCsReference</strong>(Unity-Technologies/UnityCsReference)── C#側の公式参照ソース</li><li><strong>Mono</strong>(mono/mono)── JIT・GCの実物(拾い読み)</li><li>Entities(DOTS)パッケージのソース(Package Cacheから読める)</li><li>ILSpy / dnSpy ── IL逆コンパイラ(ツール)</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>Unite/Unity公式 &quot;Understanding IL2CPP&quot; / &quot;Deep dive into DOTS&quot;</li><li>CEDEC/Unite Tokyoの最適化講演(GC・バッチング系)</li><li>Catlike Coding系のDOTS実装動画</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>UnityCsReferenceの <code>Runtime/Export/Scripting/MonoBehaviour.bindings.cs</code> など bindings 系ファイル(2世界の境界線の実物)</li><li>IL2CPPが生成した自分のコードのC++</li><li>Monoの <code>mono/metadata/boehm-gc.c</code> 周辺(眺める程度でよい)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>「UnityはC++エンジンである」とはどういう意味か。C#はどこで動くか。</li><li>Mono(JIT)とIL2CPP(AOT)の違い、iOSでAOT必須の理由は?</li><li>GCスパイクはなぜ起きるか。回避の基本戦略を3つ。</li><li><code>Destroy(obj)</code> の破棄予約と実際の破棄時点を区別せよ。破棄後の <code>obj == null</code> と <code>ReferenceEquals(obj, null)</code> の結果が異なり得る理由は?</li><li>LINQやクロージャがGC Allocを生む理由を、コンパイラが生成する コードの観点で説明せよ。</li><li>DOTSが速い理由を、第3章・第4章・第8章の言葉で1つずつ挙げよ。</li><li>SRP Batcherは何のコストを削っているか(第13章の言葉で)。</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unityゲームの1フレーム</span></span>
<span class="line"><span>─────────────────────────────────────────────────</span></span>
<span class="line"><span>[C++ネイティブ] PlayerLoop開始</span></span>
<span class="line"><span>   → 入力更新(第14章) → 物理(PhysX)</span></span>
<span class="line"><span>   → C#へブリッジ ─────────────────────┐</span></span>
<span class="line"><span>[C#マネージド]  FixedUpdate/Update/LateUpdate │← あなたのコード</span></span>
<span class="line"><span>               (Mono JIT または IL2CPP産C++)  │  GC Allocはここで発生</span></span>
<span class="line"><span>   ←──────────────────────────────────┘</span></span>
<span class="line"><span>   → アニメ → レンダラ(SRP) → コマンド生成 → GfxDevice(第13章)</span></span>
<span class="line"><span>   → GPU(第11,12章) → Present</span></span>
<span class="line"><span>─────────────────────────────────────────────────</span></span>
<span class="line"><span>プロファイラの縦軸(PlayerLoop/GC/Gfx)がこの図の各行に対応する</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Object.Destroy.html" target="_blank" rel="noreferrer">Unity 6.0: Object.Destroy</a></li><li><a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Object-operator_eq.html" target="_blank" rel="noreferrer">Unity 6.0: Object.operator ==</a></li></ul>`,30)])])}const C=e(n,[["render",o]]);export{p as __pageData,C as default};
